fn visit_ref_null(&mut self, hty: HeapType) -> Self::Output {
    match hty {
        HeapType::FUNC => {
            let ptr_type = self.env.ptr_type();
            match ptr_type {
                WasmValType::I64 => self.context.stack.push(Val::i64(0)),
